package it.comune.trieste.ouf.ingestion;
import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/internal/v1/ingestion") public class HistoricalContractApi {private final HistoricalContractService history;private final TrustedAuthorizationContext authorization;public HistoricalContractApi(HistoricalContractService history,TrustedAuthorizationContext authorization){this.history=history;this.authorization=authorization;}@GetMapping("/contracts/runs/{runId}")Map<String,Object> contracts(@PathVariable UUID runId,HttpServletRequest request){return history.runContracts(runId,authorization.require(request,"ingestion.contract.read",false));}@GetMapping("/runs/{runId}/lineage")Map<String,Object> lineage(@PathVariable UUID runId,@RequestParam(defaultValue="100")int limit,HttpServletRequest request){return Map.of("items",history.lineage(runId,authorization.require(request,"ingestion.lineage.read",false),limit));}}
